function validate([flights, days]) {
  const n = flights.length;
  if (n < 1 || n > 100) return 'flights needs 1 to 100 rows.';
  if (flights.some(row => !Array.isArray(row) || row.length !== n)) return 'flights must be an n x n matrix.';
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (flights[i][j] !== 0 && flights[i][j] !== 1) return 'Each flights entry is 0 or 1.';
    }
    if (flights[i][i] !== 0) return 'flights[i][i] must be 0.';
  }
  if (days.length !== n) return 'days needs one row per city.';
  const k = days[0].length;
  if (k < 1 || k > 100) return 'Each days row needs 1 to 100 weeks.';
  if (days.some(row => !Array.isArray(row) || row.length !== k)) return 'All days rows must have the same length.';
  if (days.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 7))) return 'Each days entry is between 0 and 7.';
  return null;
}

