function maxVacationDays(flights, days) {
  const n = flights.length;
  const k = days[0].length;
  const dp = Array.from({ length: k + 1 }, () => new Array(n).fill(0));

  for (let week = k - 1; week >= 0; week--) {
    for (let city = 0; city < n; city++) {
      for (let dest = 0; dest < n; dest++) {
        if (dest === city || flights[city][dest] === 1) {
          const total = days[dest][week] + dp[week + 1][dest];
          dp[week][city] = Math.max(dp[week][city], total);
        }
      }
    }
  }
  return dp[0][0];
}

