function maxVacationDays(flights, days) {
  // Try every possible itinerary week by week.
  const n = flights.length, k = days[0].length;
  const explore = (week, here) => {
    if (week === k) return 0;
    let best = 0;
    for (let next = 0; next < n; next++) {
      if (next !== here && !flights[here][next]) continue;
      best = Math.max(best, days[next][week] + explore(week + 1, next));
    }
    return best;
  };
  return explore(0, 0);
}

