function generate(rand, size) {
  const pick = m => Math.floor(rand() * m);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(4);
  const k = size === 'large' ? Math.min(100, Math.floor((20000 - n * n) / n)) : 1 + pick(5);
  const density = size === 'large' ? 0.02 + rand() * 0.2 : rand();
  const flights = Array.from({ length: n }, (_, i) => Array.from({ length: n }, (_, j) => (i !== j && rand() < density ? 1 : 0)));
  const style = pick(3);
  const days = Array.from({ length: n }, () => Array.from({ length: k }, () => {
    if (style === 0) return pick(8);
    if (style === 1) return rand() < 0.7 ? 0 : 1 + pick(7);
    return 5 + pick(3);
  }));
  return [flights, days];
}
